// Stores fictional practice orders only, on this browser and this origin.
window.DemoStore=(()=>{
 const key='moui-tuja.practice.v1',lock='moui-tuja.practice.write';
 const initial=()=>({startingCash:10000000,cash:4450000,holdings:[{name:'가상 종목 A',quantity:20,average:80000,price:85000},{name:'가상 종목 B',quantity:5,average:300000,price:315000},{name:'가상 종목 C',quantity:10,average:245000,price:252000}],orders:[],revision:0});
 const total=s=>s.cash+s.holdings.reduce((sum,h)=>sum+h.quantity*h.price,0);
 function quote(s,index,q,side){const h=s.holdings[index];if(!h||!['buy','sell'].includes(side)||!Number.isSafeInteger(q)||q<1||!Number.isSafeInteger(q*h.price))throw Error('1주 이상의 유효한 수량을 입력하세요.');const gross=q*h.price,fee=Math.round(gross*.00015),tax=side==='sell'?Math.round(gross*.0018):0,settlement=side==='buy'?gross+fee:gross-fee-tax;return {gross,fee,tax,settlement};}
 function check(s,index,q,side){try{const h=s.holdings[index],t=quote(s,index,q,side);if(side==='sell'&&q>h.quantity)return `보유 수량은 ${h.quantity}주입니다. 그 이하로 입력하세요.`;if(side==='buy'&&t.settlement>s.cash)return '현금이 부족합니다. 수량을 줄이거나 최대 수량을 눌러주세요.';if(side==='buy'&&(h.quantity+q)*h.price>(total(s)-t.fee)*.3)return '한 종목의 투자 한도(총자산의 30%)를 넘습니다. 수량을 줄여주세요.';return '';}catch(e){return e.message;}}
 function apply(s,o){const error=check(s,o.index,o.q,o.side);if(error)throw Error(error);const h=s.holdings[o.index],t=quote(s,o.index,o.q,o.side);if(o.side==='buy'){h.average=(h.average*h.quantity+t.gross)/(h.quantity+o.q);h.quantity+=o.q;s.cash-=t.settlement;}else{h.quantity-=o.q;s.cash+=t.settlement;if(h.quantity===0)h.average=0;}s.orders.push({...o,name:h.name,...t});s.revision++;}
 function read(){let raw;try{raw=localStorage.getItem(key);}catch{throw Error('이 브라우저에서 연습 기록을 읽을 수 없습니다. 저장 권한을 확인하세요.');}const s=initial();if(raw===null)return s;try{const data=JSON.parse(raw);if(data.version!==1||!Array.isArray(data.orders)||data.orders.length>1000)throw Error();const ids=new Set();for(const o of data.orders){if(typeof o.id!=='string'||ids.has(o.id)||!Number.isInteger(o.index)||typeof o.at!=='string'||!Number.isFinite(Date.parse(o.at)))throw Error();ids.add(o.id);apply(s,{id:o.id,index:o.index,q:o.q,side:o.side,at:o.at});}return s;}catch{throw Error('저장된 연습 기록을 읽을 수 없습니다. 기록을 덮어쓰지 않았습니다.');}}
 async function execute(order,revision){if(!navigator.locks)throw Error('안전한 기록 저장을 지원하지 않는 브라우저입니다. 최신 브라우저에서 이용해 주세요.');return navigator.locks.request(lock,()=>{const s=read();if(s.revision!==revision)throw Error('다른 화면에서 연습 기록이 변경됐습니다. 최신 금액을 확인하고 다시 주문하세요.');if(s.orders.length>=1000)throw Error('연습 주문 저장 한도(1,000건)에 도달했습니다.');apply(s,{...order,id:crypto.randomUUID(),at:new Date().toISOString()});try{localStorage.setItem(key,JSON.stringify({version:1,orders:s.orders.map(({id,index,q,side,at})=>({id,index,q,side,at}))}));}catch{throw Error('기록을 저장하지 못해 주문을 완료하지 않았습니다. 브라우저 저장 공간을 확인하세요.');}window.dispatchEvent(new Event('practicechange'));return s;});}
 function subscribe(fn){window.addEventListener('storage',e=>{if(e.key===key||e.key===null)fn();});window.addEventListener('practicechange',fn);window.addEventListener('pageshow',fn);}
 return {initial,read,quote,check,total,execute,subscribe};
})();
